ork.prefixlen != network.max_prefixlen or ip.is_loopback or ip.is_unspecified \\\\\\n                or ip.is_link_local or ip.is_multicast or ip.is_reserved:\\n            raise RuntimePlanDenied('EXACT_DESTINATION_EXEMPTIONS_REQUIRED')\\n        networks.append(network)\\n    if len(set(networks)) != len(networks):\\n        raise RuntimePlanDenied('DUPLICATE_DESTINATION_EXEMPTION')\\n    prefixes = adapter['provider']['namespace_prefixes']\\n    if not isinstance(prefixes, list) or not 1 <= len(prefixes) <= 32 \\\\\\n            or any(not isinstance(v, str) for v in prefixes) or len(set(prefixes)) != len(prefixes):\\n        raise RuntimePlanDenied('EXPLICIT_NAMESPACES_REQUIRED')\\n    tenants = adapter['admission']['tenants']\\n    if not isinstance(tenants, list) or not 1 <= len(tenants) <= 32 \\\\\\n            or any(not isinstance(v, str) for v in tenants) or len(set(tenants)) != len(tenants):\\n        raise RuntimePlanDenied('EXPLICIT_TENANTS_REQUIRED')\\n    # Native validation, with an ephemeral placeholder only to validate the\\n    # non-secret shape. Never read, generate, persist or return a receipt key.\\n    native = AdapterBinding(ProviderBinding(**adapter['provider']),\\n        AdmissionBinding(**adapter['admission']), adapter['searchPath'], adapter['fetchPath'],\\n        '0' * 64, adapter['requestTimeoutSeconds'])\\n    native.validate()\\n    routes = materialize({'routes': []}, route)\\n    for name in ('installation', 'issuer', 'audience', 'workload', 'scope', 'tenants'):\\n        if route[name] != adapter['admission'][name]:\\n            raise RuntimePlanDenied('ADMISSION_BINDING_MISMATCH')\\n    for name in ('searchPath', 'fetchPath'):\\n        if route[name] != adapter[name]:\\n            raise RuntimePlanDenied('REQUEST_PATH_MISMATCH')\\n    if route['maxRequestBytes'] != adapter['provider']['max_request_bytes']:\\n        raise RuntimePlanDenied('REQUEST_BOUND_MISMATCH')\\n    if adapter['requestTimeoutSeconds'] <= adapter['provider']['timeout_seconds'] \\\\\\n            or route['upstream']['timeout']['read'] <= adapter['requestTimeoutSeconds']:\\n        raise RuntimePlanDenied('DEADLINE_ORDER_INVALID')\\n    adapter_host = identities['adapterHostname']\\n    if route['upstream']['upstream_host'] != adapter_host \\\\\\n            or route['upstream']['nodes'] != {adapter_host + ':' + str(adapter['listenPort']): 1}:\\n        raise RuntimePlanDenied('ADAPTER_TLS_BINDING_MISMATCH')\\n    if not re.fullmatch(r'\\\\$ENV://[A-Z][A-Z0-9_]{1,127}', route['oidcSecretRef']) \\\\\\n            or route['oidcSecretRef'] == '$ENV://' + route['receiptKeyEnvironment']:\\n        raise RuntimePlanDenied('PURPOSE_SEPARATED_ENV_REFERENCES_REQUIRED')\\n    paths = [adapter[k] for k in ('receiptKeyFile', 'tlsCertificateFile', 'tlsPrivateKeyFile')]\\n    paths.append(adapter['provider']['ca_file'])\\n    for path in paths:\\n        file_reference(path)\\n    if len(set(paths)) != len(paths):\\n        raise RuntimePlanDenied('DISTINCT_RUNTIME_FILES_REQUIRED')\\n    if adapter['provider']['ca_file'] != route['tlsProfile']['trustedCertificateFile']:\\n        raise RuntimePlanDenied('TRUST_BUNDLE_BINDING_MISMATCH')\\n    # Independently derived network family is an explicit input, never inferred\\n    # from certificate names, domain names or the provider's current DNS answers.\\n    dns = config['dns']; exact(dns, ('resolvers', 'networkIPVersion', 'resolverPort'))\\n    bounded(dns['resolverPort'], 1, 65535)\\n    if type(dns['networkIPVersion']) is not int or dns['networkIPVersion'] not in (4, 6):\\n        raise RuntimePlanDenied('NETWORK_FAMILY_REQUIRED')\\n    if listener.version != dns['networkIPVersion']:\\n        raise RuntimePlanDenied('LISTENER_NETWORK_FAMILY_MISMATCH')\\n    if not isinstance(dns['resolvers'], list) or not 1 <= len(dns['resolvers']) <= 8:\\n        raise RuntimePlanDenied('RESOLVER_BINDING_REQUIRED')\\n    addresses = []\\n    for value in dns['resolvers']:\\n        if not isinstance(value, str) or '%' in value:\\n            raise RuntimePlanDenied('EXACT_RESOLVER_IP_REQUIRED')\\n        try:\\n            ip = ipaddress.ip_address(value)\\n        except ValueError:\\n            raise RuntimePlanDenied('EXACT_RESOLVER_IP_REQUIRED') from None\\n        if ip.is_loopback or ip.is_unspecified or ip.is_multicast or ip.is_link_local or ip.is_reserved:\\n            raise RuntimePlanDenied('UNUSABLE_RESOLVER_IP')\\n        addresses.append(ip)\\n    if len(set(addresses)) != len(addresses):\\n        raise RuntimePlanDenied('DUPLICATE_RESOLVER_IP')\\n    selected = [str(v) for v in addresses if v.version == dns['networkIPVersion']]\\n    deferred = [str(v) for v in addresses if v.version != dns['networkIPVersion']]\\n    if not selected:\\n        raise RuntimePlanDenied('COMPATIBLE_RESOLVER_REQUIRED')\\n    result = {'schema': 'ouf.semantic-provider-runtime-plan.v1',\\n        'adapterConfiguration': copy.deepcopy(adapter), 'southboundRoutes': routes,\\n        'tlsIdentities': copy.deepcopy(identities),\\n        'dnsBinding': {'networkIPVersion': dns['networkIPVersion'], 'selectedResolvers': selected,\\n                       'deferredResolvers': deferred,\\n                       'transportPorts': {'udp': dns['resolverPort'], 'tcp': dns['resolverPort']},\\n                       'connectivityProven': False, 'forwardingPathProven': False},\\n        'installationGates': ['TRUST_RECEIPT_AND_LEAF_MOUNTS', 'DEDICATED_SOUTHBOUND_TLS_LISTENER',\\n            'JAVA_CLIENT_TRUSTSTORE', 'ISOLATED_NETWORK_AND_KERNEL_READBACK',\\n            'DNS_ALL_ANSWER_TTL_AND_FAIL_CLOSED_REFRESH', 'DOCKER_DNS_FORWARDING_BOUNDARY',\\n            'PROVIDER_GOVERNANCE_AND_WORKLOAD_ADMISSION', 'RESTART_RENEWAL_AND_PRODUCTION_BYPASS'],\\n        'installed': False, 'providerCalls': 0, 'notReleaseAcceptance': True}\\n    if len(json.dumps(result).encode()) > 131072 or len(json.dumps(adapter).encode()) > 32768:\\n        raise RuntimePlanDenied('CONFIGURATION_TOO_LARGE')\\n    return result\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser(description=__doc__)\\n    parser.add_argument('--configuration', required=True)\\n    args = parser.parse_args()\\n    try:\\n        with Path(args.configuration).open('rb') as stream:\\n            raw = stream.read(65537)\\n        if len(raw) > 65536:\\n            raise RuntimePlanDenied('CONFIGURATION_TOO_LARGE')\\n        def unique(pairs):\\n            value = {}\\n            for key, item in pairs:\\n                if key in value:\\n                    raise RuntimePlanDenied('DUPLICATE_CONFIGURATION_KEY')\\n                value[key] = item\\n            return value\\n        result = compile_plan(json.loads(raw, object_pairs_hook=unique))\\n        print(json.dumps(result, sort_keys=True))\\n    except Exception:\\n        print('SEMANTIC_PROVIDER_RUNTIME_PLAN=BLOCKED NO_INSTALLATION=true NO_SECRETS_PRINTED=true')\\n        raise SystemExit(1) from None\\n\\n\\nif __name__ == '__main__':\\n    main()\\n\",\"tools/materialize_semantic_provider.py\":\"\\\"\\\"\\\"Add two explicitly installed, workload-only provider routes without live writes.\\\"\\\"\\\"\\nimport copy\\nimport json\\nfrom pathlib import Path\\nimport re\\nfrom urllib.parse import urlsplit\\nfrom tools.semantic_provider_admission import AdmissionBinding\\n\\n\\ndef materialize(existing, config):\\n    required = {'installation', 'issuer', 'audience', 'workload', 'scope', 'tenants',\\n                'searchPath', 'fetchPath', 'searchRouteId', 'fetchRouteId',\\n                'receiptKeyEnvironment', 'oidcSecretRef', 'upstream', 'tlsProfile', 'rateLimit', 'maxRequestBytes'}\\n    if not isinstance(config, dict) or set(config) != required:\\n        raise ValueError('explicit provider installation binding required')\\n    binding = AdmissionBinding(*(config[k] for k in ('installation', 'issuer', 'audience', 'workload', 'scope', 'tenants')))\\n    binding.validate()\\n    parsed = urlsplit(binding.issuer)\\n    if parsed.scheme != 'https' or not parsed.hostname or parsed.username or parsed.password or parsed.query or parsed.fragment:\\n        raise ValueError('safe issuer required')\\n    if not isinstance(config['receiptKeyEnvironment'], str) or not re.fullmatch('[A-Z][A-Z0-9_]{1,127}', config['receiptKeyEnvironment']):\\n        raise ValueError('receipt key environment required')\\n    if config['receiptKeyEnvironment'] in {'OUF_GATEWAY_DELEGATION_KEY','OUF_SEMANTIC_READ_OWNER_KEY'}:\\n        raise ValueError('purpose-separated provider receipt key required')\\n    if not isinstance(config['oidcSecretRef'], str) or not config['oidcSecretRef'].startswith(('$ENV://', '$secret://')):\\n        raise ValueError('OIDC secret reference required')\\n    ids = [config['searchRouteId'], config['fetchRouteId']]\\n    paths = [config['searchPath'], config['fetchPath']]\\n    if len(set(ids)) != 2 or any(not isinstance(v, str) or not re.fullmatch('[A-Za-z0-9_-]{1,128}', v) for v in ids):\\n        raise ValueError('distinct route IDs required')\\n    if len(set(paths)) != 2 or any(not isinstance(v, str) or not re.fullmatch(r'/[A-Za-z0-9_/-]{1,200}', v)\\n                                  or '//' in v or v.endswith('/') for v in paths):\\n        raise ValueError('distinct exact paths required')\\n    max_bytes = config['maxRequestBytes']\\n    if type(max_bytes) is not int or not 1 <= max_bytes <= 65536:\\n        raise ValueError('bounded request size required')\\n    upstream = config['upstream']\\n    if not isinstance(upstream, dict) or set(upstream) != {'type', 'scheme', 'nodes', 'pass_host', 'upstream_host', 'timeout'} \\\\\\n            or upstream.get('type') != 'roundrobin' or upstream.get('scheme') != 'https' \\\\\\n            or not upstream.get('nodes') \\\\\\n            or upstream.get('pass_host') != 'rewrite' or not upstream.get('upstream_host'):\\n        raise ValueError('explicit certificate-verified HTTPS adapter binding required')\\n    if not isinstance(upstream['nodes'], dict) or len(upstream['nodes']) != 1 \\\\\\n            or not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9.-]{0,252}', upstream['upstream_host']):\\n        raise ValueError('exact installed adapter endpoint and trust binding required')\\n    for node, weight in upstream['nodes'].items():\\n        endpoint = urlsplit('https://'+node)\\n        if not endpoint.hostname or endpoint.port is None or endpoint.port < 1 or weight != 1 \\\\\\n                or endpoint.username or endpoint.password or endpoint.path or endpoint.query or endpoint.fragment:\\n            raise ValueError('explicit adapter host and port required')\\n    timeout = upstream['timeout']\\n    if not isinstance(timeout, dict) or set(timeout) != {'connect', 'send', 'read'} \\\\\\n            or any(type(v) is not int or not 1 <= v <= 60 for v in timeout.values()):\\n        raise ValueError('bounded adapter upstream timeouts required')\\n    # APISIX 3.18's upstream.tls.verify is Kafka-only, not HTTPS enforcement.\\n    # Require the explicit NGINX verification/trust profile for a separately\\n    # governed southbound role; a route alone cannot enable this global setting.\\n    tls = config['tlsProfile']\\n    if not isinstance(tls, dict) or set(tls) != {'role', 'mode', 'trustedCertificateFile', 'verifyDepth'} \\\\\\n            or tls['role'] != 'DEDICATED_SOUTHBOUND' or tls['mode'] != 'NGINX_PROXY_SSL_VERIFY' \\\\\\n            or not isinstance(tls['trustedCertificateFile'], str) \\\\\\n            or not re.fullmatch(r'/[A-Za-z0-9_./-]{1,255}', tls['trustedCertificateFile']) \\\\\\n            or '..' in tls['trustedCertificateFile'].split('/') \\\\\\n            or type(tls['verifyDepth']) is not int or not 1 <= tls['verifyDepth'] <= 5:\\n        raise ValueError('explicit dedicated southbound NGINX TLS profile required')\\n    rate = config['rateLimit']\\n    if not isinstance(rate, dict) or set(rate) != {'count', 'time_window', 'key_type', 'key', 'policy', 'rejected_code'} \\\\\\n            or type(rate.get('count')) is not int or not 1 <= rate['count'] <= 1000 \\\\\\n            or type(rate.get('time_window')) is not int or not 1 <= rate['time_window'] <= 3600 \\\\\\n            or rate.get('key_type') != 'var' or rate.get('key') != 'remote_addr' \\\\\\n            or rate.get('policy') != 'local' or rate.get('rejected_code') != 429:\\n        raise ValueError('explicit bounded rate limit required')\\n    if not isinstance(existing, dict) or not isinstance(existing.get('routes'), list):\\n        raise ValueError('existing route snapshot required')\\n    if any(route.get('id') in ids or route.get('uri') in paths for route in existing['routes']):\\n        raise ValueError('provider binding already exists; reconcile before installation')\\n    result = copy.deepcopy(existing)\\n    if 'providerTLSRequirement' in result:\\n        raise ValueError('provider TLS requirement already exists; reconcile first')\\n    result['providerTLSRequirement'] = {'role': tls['role'], 'mode': tls['mode'],\\n        'apisixSSLTrustedCertificate': tls['trustedCertificateFile'],\\n        'nginxHTTPConfigurationSnippet': 'proxy_ssl_verify on;\\\\nproxy_ssl_verify_depth '+str(tls['verifyDepth'])+';',\\n        'installed': False}\\n    template = (Path(__file__).parent/'lua/admit_semantic_provider.lua').read_text()\\n    constants = {'INSTALLATION': binding.installation, 'ISSUER': binding.issuer, 'AUDIENCE': binding.audience,\\n                 'WORKLOAD': binding.workload, 'SCOPE': binding.scope, 'RECEIPT_KEY_ENV': config['receiptKeyEnvironment']}\\n    prefix = '\\\\n'.join('local '+key+'='+json.dumps(value) for key, value in constants.items())\\n    prefix += '\\\\nlocal TENANTS={'+','.join('['+json.dumps(v)+']=true' for v in binding.tenants)+'}\\\\n'\\n    strip = \\\"return function(conf,ctx) for name,_ in pairs(ngx.req.get_headers(0)) do if name:lower():sub(1,6)=='x-ouf-' then ngx.req.clear_header(name) end end end\\\"\\n    for name, method in (('search', 'POST'), ('fetch', 'GET')):\\n        lua = 'return function(conf,ctx)\\\\n'+prefix+'local METHOD='+json.dumps(method)+'\\\\nlocal PATH='+json.dumps(config[name+'Path'])+'\\\\nlocal MAX_REQUEST_BYTES='+str(max_bytes)+'\\\\n'+template+'\\\\nend'\\n        result['routes'].append({'id': config[name+'RouteId'], 'uri': config[name+'Path'], 'methods': [method],\\n            'labels': {'ouf-managed': 'true', 'ouf-installation': binding.installation, 'ouf-mediation': 'semantic-provider-transport-v1'},\\n            'plugins': {'client-control': {'max_body_size': max_bytes}, 'limit-count': copy.deepcopy(rate),\\n                'serverless-pre-function': {'phase': 'rewrite', 'functions': [strip]},\\n                'openid-connect': {'client_id': binding.audience, 'client_secret': config['oidcSecretRef'],\\n                    'discovery': binding.issuer.rstrip('/')+'/.well-known/openid-configuration',\\n                    'bearer_only': True, 'unauth_action': 'deny', 'use_jwks': True, 'ssl_verify': True,\\n                    'required_scopes': [binding.scope],\\n                    'claim_validator': {'audience': {'required': True, 'match_with_client_id': True}},\\n                    'set_access_token_header': False, 'set_id_token_header': False, 'set_userinfo_header': False},\\n                'serverless-post-function': {'phase': 'access', 'functions': [lua]}},\\n            'upstream': {**copy.deepcopy(upstream), 'retries': 0}})\\n    return result\\n\",\"tools/materialize_semantic_provider_tls.py\":\"\\\"\\\"\\\"Private APISIX TLS-only bootstrap; returned resources contain a private key.\\n\\nNo CLI, file/network I/O, key generation, installation or northbound modification.\\nThe caller must verify existing trust/leaf/role bindings and protect output files.\\n\\\"\\\"\\\"\\nimport copy\\nimport ipaddress\\nimport re\\n\\nfrom tools.materialize_semantic_provider import materialize\\nfrom tools.materialize_semantic_provider_runtime import exact, bounded, hostname\\n\\n\\nclass TLSBootstrapDenied(ValueError):\\n    pass\\n\\n\\ndef materialize_tls(route_binding, transport, *, certificate_pem, private_key_pem):\\n    exact(transport, ('listenAddress', 'listenPort', 'serverHostname', 'sslResourceId'))\\n    bounded(transport['listenPort'], 1024, 65535)\\n    hostname(transport['serverHostname'])\\n    try:\\n        address = ipaddress.ip_address(transport['listenAddress'])\\n    except (ValueError, TypeError):\\n        raise TLSBootstrapDenied('NUMERIC_TLS_LISTENER_REQUIRED') from None\\n    if address.is_multicast or address.is_link_local:\\n        raise TLSBootstrapDenied('TLS_LISTENER_INVALID')\\n    if not isinstance(transport['sslResourceId'], str) or not re.fullmatch(\\n            r'[A-Za-z0-9_-]{1,128}', transport['sslResourceId']):\\n        raise TLSBootstrapDenied('SSL_RESOURCE_ID_REQUIRED')\\n    # Structural bounds only. Signature, expiry, exact hostname and key-pair\\n    # verification must be performed by the private installation preparer.\\n    if not isinstance(certificate_pem, str) or not certificate_pem.isascii() \\\\\\n            or not 128 <= len(certificate_pem) <= 65536 \\\\\\n            or not certificate_pem.startswith('-----BEGIN CERTIFICATE-----\\\\n') \\\\\\n            or not certificate_pem.rstrip().endswith('-----END CERTIFICATE-----') \\\\\\n            or 'PRIVATE KEY' in certificate_pem:\\n        raise TLSBootstrapDenied('BOUNDED_SERVER_CERTIFICATE_REQUIRED')\\n    if not isinstance(private_key_pem, str) or not private_key_pem.isascii() \\\\\\n            or not 64 <= len(private_key_pem) <= 65536 \\\\\\n            or not re.fullmatch(r'-----BEGIN ((?:EC |RSA )?PRIVATE KEY)-----\\\\n[A-Za-z0-9+/=\\\\n]+-----END \\\\1-----\\\\s*', private_key_pem):\\n        raise TLSBootstrapDenied('BOUNDED_SERVER_PRIVATE_KEY_REQUIRED')\\n    plan = materialize({'routes': []}, route_binding)\\n    if transport['serverHostname'] == route_binding['upstream']['upstream_host']:\\n        raise TLSBootstrapDenied('DISTINCT_TLS_ROLE_IDENTITIES_REQUIRED')\\n    tls = plan['providerTLSRequirement']\\n    runtime = {'apisix': {\\n        'node_listen': [], 'enable_admin': False, 'enable_control': False,\\n        'enable_ipv6': address.version == 6, 'enable_http2': False,\\n        'ssl': {'enable': True, 'listen': [{'ip': str(address), 'port': transport['listenPort'], 'enable_http3': False}],\\n                'ssl_protocols': 'TLSv1.2 TLSv1.3', 'ssl_session_tickets': False,\\n                'ssl_trusted_certificate': tls['apisixSSLTrustedCertificate']}},\\n        'deployment': {'role': 'data_plane', 'role_data_plane': {'config_provider': 'yaml'}},\\n        'plugins': ['client-control', 'limit-count', 'openid-connect', 'serverless-pre-function', 'serverless-post-function'],\\n        'nginx_config': {'envs': [route_binding['oidcSecretRef'].removeprefix('$ENV://'),\\n                                  route_binding['receiptKeyEnvironment']],\\n            'http_configuration_snippet': tls['nginxHTTPConfigurationSnippet']}}\\n    if not re.fullmatch(r'\\\\$ENV://[A-Z][A-Z0-9_]{1,127}', route_binding['oidcSecretRef']) \\\\\\n            or runtime['nginx_config']['envs'][0] == runtime['nginx_config']['envs'][1]:\\n        raise TLSBootstrapDenied('DISTINCT_ENV_REFERENCES_REQUIRED')\\n    resources = {'routes': copy.deepcopy(plan['routes']), 'ssls': [{\\n        'id': transport['sslResourceId'], 'type': 'server', 'status': 1,\\n        'snis': [transport['serverHostname']], 'cert': certificate_pem, 'key': private_key_pem,\\n        'ssl_protocols': ['TLSv1.2', 'TLSv1.3'],\\n        'labels': {'ouf-managed': 'true', 'ouf-installation': route_binding['installation']}}]}\\n    # APISIX 3.18 cli/ops.lua sets placeholder cert/key paths unconditionally;\\n    # the real server certificate is selected by this exact SNI SSL resource.\\n    return {'runtimeConfiguration': runtime, 'resources': resources,\\n        'containsPrivateKey': True, 'certificateCryptographicallyVerified': False,\\n        'installed': False, 'providerCalls': 0, 'notReleaseAcceptance': True}\\n\",\"tools/southbound_security.py\":\"import ipaddress\\nimport socket\\nfrom dataclasses import dataclass\\nfrom urllib.parse import urlparse, urljoin\\n\\n\\nclass SouthboundDenied(RuntimeError): pass\\n\\n\\n@dataclass(frozen=True)\\nclass RegisteredEndpoint:\\n    scheme: str\\n    host: str\\n    port: int\\n    allowed_cidrs: tuple[str, ...] = ()\\n\\n\\ndef _forbidden(ip: ipaddress._BaseAddress) -> bool:\\n    return ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_unspecified or ip.is_reserved\\n\\n\\ndef validate_destination(url: str, registered: RegisteredEndpoint, resolver=socket.getaddrinfo) -> tuple[str, ...]:\\n    parsed=urlparse(url)\\n    if parsed.username or parsed.password or parsed.fragment: raise SouthboundDenied(\\\"UNSAFE_URL_COMPONENT\\\")\\n    if parsed.scheme != registered.scheme or parsed.hostname != registered.host or (parsed.port or (443 if parsed.scheme=='https' else 80)) != registered.port:\\n        raise SouthboundDenied(\\\"UNREGISTERED_ENDPOINT\\\")\\n    if parsed.scheme != 'https': raise SouthboundDenied(\\\"TLS_REQUIRED\\\")\\n    try: answers=resolver(parsed.hostname,registered.port,type=socket.SOCK_STREAM)\\n    except OSError as exc: raise SouthboundDenied(\\\"DNS_RESOLUTION_FAILED\\\") from exc\\n    ips=tuple(sorted({item[4][0] for item in answers}))\\n    if not ips: raise SouthboundDenied(\\\"DNS_RESOLUTION_EMPTY\\\")\\n    networks=tuple(ipaddress.ip_network(cidr) for cidr in registered.allowed_cidrs)\\n    for raw in ips:\\n        ip=ipaddress.ip_address(raw)\\n        if _forbidden(ip): raise SouthboundDenied(\\\"FORBIDDEN_ADDRESS_CLASS\\\")\\n        if ip.is_private and not networks: raise SouthboundDenied(\\\"PRIVATE_ADDRESS_UNREGISTERED\\\")\\n        if networks and not any(ip in network for network in networks): raise SouthboundDenied(\\\"DNS_REBINDING_OR_CIDR_MISMATCH\\\")\\n    return ips\\n\\n\\ndef validate_redirect(current_url: str, location: str, registered: RegisteredEndpoint, resolver=socket.getaddrinfo) -> str:\\n    target=urljoin(current_url,location)\\n    validate_destination(target,registered,resolver)\\n    return target\\n\",\"tools/semantic_provider_adapter.py\":\"\\\"\\\"\\\"TLS-only bounded transport, invoked as python -B -m tools.semantic_provider_adapter.\\n\\nLinux fork workers isolate elapsed-time limits and bound concurrent connections.\\nThis is a Gateway transport component, not semantic discovery orchestration.\\n\\\"\\\"\\\"\\nimport argparse\\nfrom dataclasses import dataclass\\nimport json\\nimport os\\nfrom pathlib import Path\\nimport re\\nimport socket\\nimport ssl\\nimport stat\\nfrom http.server import BaseHTTPRequestHandler, HTTPServer\\nfrom socketserver import ForkingMixIn\\nfrom urllib.parse import urlsplit\\n\\nfrom tools import semantic_provider_relay as relay\\nfrom tools.semantic_provider_admission import AdmissionBinding, AdmissionDenied, HEADER, receipt_key, verify\\nfrom tools.semantic_provider_boundary import ProviderRequestDenied\\nfrom tools.southbound_security import SouthboundDenied\\n\\n\\nclass AdapterDenied(ValueError):\\n    pass\\n\\n\\ndef private_file(path, max_bytes):\\n    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)\\n    try:\\n        info = os.fstat(fd)\\n        if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_uid != os.geteuid() \\\\\\n                or stat.S_IMODE(info.st_mode) & 0o077 or info.st_size > max_bytes:\\n            raise AdapterDenied('PRIVATE_FILE_REQUIRED')\\n        raw = os.read(fd, max_bytes + 1)\\n        if len(raw) > max_bytes:\\n            raise AdapterDenied('PRIVATE_FILE_REQUIRED')\\n        return raw\\n    finally:\\n        os.close(fd)\\n\\n\\n@dataclass(frozen=True)\\nclass AdapterBinding:\\n    provider: relay.ProviderBinding\\n    admission: AdmissionBinding\\n    search_path: str\\n    fetch_path: str\\n    receipt_key: str\\n    request_timeout_seconds: int = 20\\n\\n    def validate(self):\\n        self.provider.validate(); self.admission.validate(); receipt_key(self.receipt_key)\\n        for path in (self.search_path, self.fetch_path):\\n            if not isinstance(path, str) or not re.fullmatch(r'/[A-Za-z0-9_/-]{1,200}', path) \\\\\\n                    or '//' in path or path.endswith('/'):\\n                raise AdapterDenied('ADAPTER_PATH_INVALID')\\n        if self.search_path == self.fetch_path or type(self.request_timeout_seconds) is not int \\\\\\n                or not 1 <= self.request_timeout_seconds <= 60:\\n            raise AdapterDenied('ADAPTER_BINDING_INVALID')\\n\\n\\ndef dispatch(binding, method, target, headers, body, *, provider_search=relay.search, provider_fetch=relay.fetch):\\n    \\\"\\\"\\\"Authenticate exact received bytes before grammar validation, DNS or provider I/O.\\\"\\\"\\\"\\n    if not isinstance(target, str) or len(target) > 6144 or not target.isascii() \\\\\\n            or re.search(r'[\\\\x00-\\\\x20\\\\x7f]', target) or not target.startswith('/'):\\n        raise AdapterDenied('REQUEST_TARGET_INVALID')\\n    parsed = urlsplit(target)\\n    if parsed.scheme or parsed.netloc or parsed.fragment:\\n        raise AdapterDenied('REQUEST_TARGET_INVALID')\\n    operation = None\\n    if method == 'POST' and parsed.path == binding.search_path and not parsed.query:\\n        operation = 'search'\\n    if method == 'GET' and parsed.path == binding.fetch_path and parsed.query:\\n        operation = 'fetch'\\n    if operation is None:\\n        raise AdapterDenied('REQUEST_ROUTE_REJECTED')\\n    receipts = headers.get_all(HEADER, [])\\n    if len(receipts) != 1:\\n        raise AdmissionDenied('RECEIPT_INVALID')\\n    if headers.get_all('Authorization', []):\\n        raise AdmissionDenied('CALLER_CREDENTIAL_FORBIDDEN')\\n    if len(body) > binding.provider.max_request_bytes:\\n        raise AdapterDenied('REQUEST_TOO_LARGE')\\n    verify(binding.admission, binding.receipt_key, receipts[0], method, target, body)\\n    if operation == 'search':\\n        media = headers.get_all('Content-Type', [])\\n        if len(media) != 1 or media[0].lower() not in (\\n                'application/x-www-form-urlencoded', 'application/x-www-form-urlencoded; charset=utf-8'):\\n            raise AdapterDenied('REQUEST_MEDIA_REJECTED')\\n        return provider_search(binding.provider, body)\\n    if body:\\n        raise AdapterDenied('REQUEST_BODY_FORBIDDEN')\\n    return provider_fetch(binding.provider, parsed.query.encode('ascii'))\\n\\n\\ndef handler_for(binding):\\n    class Handler(BaseHTTPRequestHandler):\\n        server_version = 'OUF'; sys_version = ''; protocol_version = 'HTTP/1.0'\\n\\n        def log_message(self, *args):\\n            pass  # Request URI, candidate query, receipts and credentials are never logged.\\n\\n        def handle_request(self):\\n            self.close_connection = True\\n            status = 400; payload = b'{\\\"error\\\":\\\"PROVIDER_REQUEST_REJECTED\\\"}'; media = 'application/json'\\n            scope = None\\n            try:\\n                if len(self.path) > 6144 or self.headers.get_all('Transfer-Encoding', []) \\\\\\n                        or self.headers.get_all('Content-Encoding', []) or self.headers.get_all('Expect', []):\\n                    raise AdapterDenied('REQUEST_FRAMING_REJECTED')\\n                lengths = self.headers.get_all('Content-Length', [])\\n                if len(lengths) > 1 or (lengths and not re.fullmatch(r'[0-9]{1,6}', lengths[0])):\\n                    raise AdapterDenied('REQUEST_FRAMING_REJECTED')\\n                size = int(lengths[0]) if lengths else 0\\n                if size > binding.provider.max_request_bytes or (self.command == 'POST' and not lengths):\\n                    raise AdapterDenied('REQUEST_TOO_LARGE')\\n                body = self.rfile.read(size)\\n                if len(body) != size:\\n                    raise AdapterDenied('REQUEST_INCOMPLETE')\\n                result = dispatch(binding, self.command, self.path, self.headers, body)\\n                status, payload, media, scope = 200, result.body, result.media_type, result.rdf_scope\\n            except AdmissionDenied:\\n                status = 403; payload = b'{\\\"error\\\":\\\"PROVIDER_ADMISSION_DENIED\\\"}'\\n            except (AdapterDenied, ProviderRequestDenied):\\n                pass\\n            except (relay.RelayDenied, SouthboundDenied):\\n                status = 502; payload = b'{\\\"error\\\":\\\"PROVIDER_UNAVAILABLE\\\"}'\\n            except Exception:\\n                status = 503; payload = b'{\\\"error\\\":\\\"PROVIDER_UNAVAILABLE\\\"}'\\n            self.send_response(status); self.send_header('Content-Type', media)\\n            self.send_header('Content-Length', str(len(payload))); self.send_header('Cache-Control', 'no-store')\\n            self.send_header('Connection', 'close')\\n            if scope:\\n                self.send_header('X-OUF-RDF-Scope', scope)\\n            self.end_headers(); self.wfile.write(payload)\\n\\n        do_POST = handle_request\\n        do_GET = handle_request\\n\\n        def send_error(self, code, message=None, explain=None):\\n            self.close_connection = True\\n            raw = b'{\\\"error\\\":\\\"PROVIDER_REQUEST_REJECTED\\\"}'\\n            self.send_response(code); self.send_header('Content-Type', 'application/json')\\n            self.send_header('Content-Length', str(len(raw))); self.send_header('Connection', 'close')\\n            self.end_headers(); self.wfile.write(raw)\\n\\n    return Handler\\n\\n\\nclass BoundedTLSServer(ForkingMixIn, HTTPServer):\\n    block_on_close = True\\n    request_queue_size = 8\\n\\n    def __init__(self, address, binding, context, max_children):\\n        if type(max_children) is not int or not 1 <= max_children <= 16:\\n            raise AdapterDenied('WORKER_LIMIT_INVALID')\\n        binding.validate()\\n        self.binding, self.context, self.max_children = binding, context, max_children\\n        if ':' in address[0]:\\n            self.address_family = socket.AF_INET6\\n        super().__init__(address, handler_for(binding))\\n\\n    def finish_request(self, request, client_address):\\n        # Fork child is a main thread. TLS handshake, headers, body, relay and write\\n        # share one deadline, including slow/incomplete incoming connections.\\n        request.settimeout(self.binding.request_timeout_seconds)\\n        with relay.request_deadline(self.binding.request_timeout_seconds):\\n            with self.context.wrap_socket(request, server_side=True) as protected:\\n                self.RequestHandlerClass(protected, client_address, self)\\n\\n    def handle_error(self, request, client_address):\\n        pass  # No traceback/exception may disclose queries, config paths or TLS data.\\n\\n\\ndef load_configuration(path):\\n    with Path(path).open('rb') as stream:\\n        raw = stream.read(32769)\\n    if len(raw) > 32768:\\n        raise AdapterDenied('CONFIGURATION_TOO_LARGE')\\n    cfg = json.loads(raw)\\n    expected = {'listenAddress', 'listenPort', 'maxWorkers', 'requestTimeoutSeconds',\\n                'searchPath', 'fetchPath', 'provider', 'admission', 'receiptKeyFile',\\n                'tlsCertificateFile', 'tlsPrivateKeyFile'}\\n    if not isinstance(cfg, dict) or set(cfg) != expected:\\n        raise AdapterDenied('CONFIGURATION_INVALID')\\n    if not isinstance(cfg['listenAddress'], str) or not cfg['listenAddress'] \\\\\\n            or type(cfg['listenPort']) is not int or not 1 <= cfg['listenPort'] <= 65535:\\n        raise AdapterDenied('LISTENER_BINDING_INVALID')\\n    key = private_file(cfg['receiptKeyFile'], 256).decode('ascii').strip()\\n    binding = AdapterBinding(relay.ProviderBinding(**cfg['provider']), AdmissionBinding(**cfg['admission']),\\n                             cfg['searchPath'], cfg['fetchPath'], key, cfg['requestTimeoutSeconds'])\\n    binding.validate()\\n    private_file(cfg['tlsPrivateKeyFile'], 32768)\\n    context = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)\\n    context.minimum_version = ssl.TLSVersion.TLSv1_2\\n    context.load_cert_chain(cfg['tlsCertificateFile'], cfg['tlsPrivateKeyFile'])\\n    return cfg, binding, context\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser(description=__doc__)\\n    parser.add_argument('--configuration', required=True)\\n    args = parser.parse_args()\\n    try:\\n        if os.geteuid() == 0:\\n            raise AdapterDenied('NON_ROOT_REQUIRED')\\n        cfg, binding, context = load_configuration(args.configuration)\\n        with BoundedTLSServer((cfg['listenAddress'], cfg['listenPort']), binding, context, cfg['maxWorkers']) as server:\\n            server.serve_forever()\\n    except Exception:\\n        print('SEMANTIC_PROVIDER_ADAPTER=BLOCKED NO_SECRETS_PRINTED=true')\\n        raise SystemExit(1) from None\\n\\n\\nif __name__ == '__main__':\\n    main()\\n\",\"tools/semantic_provider_admission.py\":\"\\\"\\\"\\\"Purpose-separated Gateway receipts for the bounded provider transport.\\n\\nOnly APISIX after OIDC admission may mint these receipts. Incoming identity\\nheaders and bearer tokens are never an authority at the transport adapter.\\n\\\"\\\"\\\"\\nimport base64\\nfrom dataclasses import dataclass\\nimport hashlib\\nimport hmac\\nimport json\\nimport re\\nimport time\\n\\nPURPOSE = 'ouf-semantic-provider-owner-v1'\\nHEADER = 'X-OUF-Semantic-Provider-Receipt'\\nFIELDS = {'purpose', 'installation', 'issuer', 'audience', 'workload', 'tenant',\\n          'subject', 'actor', 'scope', 'requestHash', 'iat', 'exp'}\\n\\n\\nclass AdmissionDenied(ValueError):\\n    pass\\n\\n\\ndef receipt_key(value):\\n    if not isinstance(value, str) or not re.fullmatch('[0-9a-fA-F]{64}', value):\\n        raise AdmissionDenied('RECEIPT_KEY_INVALID')\\n    # Match the existing Gateway convention: hexadecimal text is the HMAC key.\\n    return value.encode('ascii')\\n\\n\\ndef request_hash(method, target, body):\\n    return hashlib.sha256(method.encode('ascii') + b'\\\\n' + target.encode('ascii') + b'\\\\n' + body).hexdigest()\\n\\n\\n@dataclass(frozen=True)\\nclass AdmissionBinding:\\n    installation: str\\n    issuer: str\\n    audience: str\\n    workload: str\\n    scope: str\\n    tenants: tuple[str, ...]\\n\\n    def validate(self):\\n        if not isinstance(self.tenants, (tuple, list)) or not self.tenants:\\n            raise AdmissionDenied('ADMISSION_BINDING_INVALID')\\n        values = [self.installation, self.issuer, self.audience, self.workload, self.scope, *self.tenants]\\n        if any(not isinstance(v, str) or not v or len(v) > 512\\n                                   or not v.isascii()\\n                or re.search(r'[\\\\x00-\\\\x20\\\\x7f]', v) for v in values):\\n            raise AdmissionDenied('ADMISSION_BINDING_INVALID')\\n        if not self.issuer.startswith('https://'):\\n            raise AdmissionDenied('ADMISSION_BINDING_INVALID')\\n\\n\\ndef no_duplicates(pairs):\\n    result = {}\\n    for key, value in pairs:\\n        if key in result:\\n            raise AdmissionDenied('RECEIPT_INVALID')\\n        result[key] = value\\n    return result\\n\\n\\ndef verify(binding, key, receipt, method, target, body, *, now=None):\\n    binding.validate()\\n    key_bytes = receipt_key(key)\\n    if not isinstance(receipt, str) or len(receipt) > 4096:\\n        raise AdmissionDenied('RECEIPT_INVALID')\\n    match = re.fullmatch(r'([A-Za-z0-9_-]+)\\\\.([0-9a-f]{64})', receipt)\\n    if not match:\\n        raise AdmissionDenied('RECEIPT_INVALID')\\n    encoded, signature = match.groups()\\n    expected = hmac.new(key_bytes, (PURPOSE + '.' + encoded).encode('ascii'), hashlib.sha256).hexdigest()\\n    if not hmac.compare_digest(expected, signature):\\n        raise AdmissionDenied('RECEIPT_INVALID')\\n    try:\\n        raw = base64.b64decode(encoded + '=' * (-len(encoded) % 4), altchars=b'-_', validate=True)\\n        if base64.urlsafe_b64encode(raw).decode().rstrip('=') != encoded:\\n            raise ValueError()\\n        claims = json.loads(raw, object_pairs_hook=no_duplicates)\\n    except (ValueError, UnicodeError):\\n        raise AdmissionDenied('RECEIPT_INVALID') from None\\n    if not isinstance(claims, dict) or set(claims) != FIELDS:\\n        raise AdmissionDenied('RECEIPT_INVALID')\\n    required = {'purpose': PURPOSE, 'installation': binding.installation, 'issuer': binding.issuer,\\n                'audience': binding.audience, 'workload': binding.workload, 'actor': 'SERVICE',\\n                'scope': binding.scope, 'requestHash': request_hash(method, target, body)}\\n    if any(claims[k] != value for k, value in required.items()):\\n        raise AdmissionDenied('RECEIPT_CONTEXT_REJECTED')\\n    if claims['tenant'] not in binding.tenants or not isinstance(claims['subject'], str) \\\\\\n            or not claims['subject'] or len(claims['subject']) > 512 \\\\\\n            or re.search(r'[\\\\x00-\\\\x20\\\\x7f]', claims['subject']):\\n        raise AdmissionDenied('RECEIPT_CONTEXT_REJECTED')\\n    instant = time.time() if now is None else now\\n    if type(claims['iat']) is not int or type(claims['exp']) is not int \\\\\\n            or not claims['iat'] <= instant < claims['exp'] \\\\\\n            or not 0 < claims['exp'] - claims['iat'] <= 30:\\n        raise AdmissionDenied('RECEIPT_EXPIRED')\\n    # READ-only transport: bounded receipts can be replayed until their expiry.\\n    # Rate limits belong to Gateway; these are not mutation/idempotency receipts.\\n    return claims\\n\",\"tools/semantic_provider_relay.py\":\"\\\"\\\"\\\"Bounded fixed-endpoint transport for the Semantic provider southbound adapter.\\n\\nGateway HTTP wiring, admission proofs and OS egress policy are separate installation\\nprerequisites. This module has no listening socket and must not be exposed directly.\\n\\\"\\\"\\\"\\nimport contextlib\\nfrom dataclasses import dataclass\\nimport http.client\\nimport ipaddress\\nimport json\\nimport signal\\nimport socket\\nimport ssl\\nimport threading\\nimport time\\nfrom urllib.parse import urlencode, urlsplit\\n\\nfrom tools.semantic_provider_boundary import (\\n    ProviderRequestDenied, validate_provider_endpoint, validate_search_form, validate_fetch_form,\\n)\\nfrom tools.southbound_security import RegisteredEndpoint, SouthboundDenied, validate_destination\\n\\n\\nclass RelayDenied(RuntimeError):\\n    pass\\n\\n\\n@dataclass(frozen=True)\\nclass ProviderBinding:\\n    endpoint: str\\n    namespace_prefixes: tuple[str, ...]\\n    allowed_cidrs: tuple[str, ...] = ()\\n    max_request_bytes: int = 65536\\n    max_response_bytes: int = 8388608\\n    max_intent_chars: int = 2000\\n    timeout_seconds: int = 10\\n    ca_file: str | None = None\\n\\n    def validate(self):\\n        validate_provider_endpoint(self.endpoint)\\n        if (not self.namespace_prefixes or type(self.max_request_bytes) is not int\\n                or not 1 <= self.max_request_bytes <= 65536 or type(self.max_response_bytes) is not int\\n                or not 1 <= self.max_response_bytes <= 8388608 or type(self.timeout_seconds) is not int\\n                or not 1 <= self.timeout_seconds <= 30):\\n            raise RelayDenied('PROVIDER_BINDING_INVALID')\\n        # Validate installed namespace boundaries without initiating a network call.\\n        sample = urlencode({'uri': self.namespace_prefixes[0] + 'binding-check'}).encode()\\n        validate_fetch_form(sample, max_bytes=self.max_request_bytes, namespace_prefixes=self.namespace_prefixes)\\n        for cidr in self.allowed_cidrs:\\n            ipaddress.ip_network(cidr)\\n\\n\\n@dataclass(frozen=True)\\nclass ProviderResponse:\\n    body: bytes\\n    media_type: str\\n    rdf_scope: str | None = None\\n\\n\\n@contextlib.contextmanager\\ndef request_deadline(seconds):\\n    # POSIX main-process execution bounds DNS, TCP, TLS, headers and body receipt.\\n    # A threaded HTTP adapter must use a separate bounded worker process instead.\\n    if threading.current_thread() is not threading.main_thread():\\n        raise RelayDenied('BOUNDED_WORKER_PROCESS_REQUIRED')\\n    previous = signal.getsignal(signal.SIGALRM)\\n    previous_timer = signal.getitimer(signal.ITIMER_REAL)\\n    started = time.monotonic()\\n    def expired(signum, frame):\\n        raise RelayDenied('PROVIDER_TIMEOUT')\\n    signal.signal(signal.SIGALRM, expired)\\n    signal.setitimer(signal.ITIMER_REAL, min(seconds, previous_timer[0]) if previous_timer[0] else seconds)\\n    try:\\n        yield\\n    finally:\\n        signal.setitimer(signal.ITIMER_REAL, 0); signal.signal(signal.SIGALRM, previous)\\n        if previous_timer[0]:\\n            remaining = previous_timer[0] - (time.monotonic() - started)\\n            if remaining <= 0:\\n                if callable(previous):\\n                    previous(signal.SIGALRM, None)\\n                else:\\n                    raise RelayDenied('PROVIDER_TIMEOUT')\\n            signal.setitimer(signal.ITIMER_REAL, remaining, previous_timer[1])\\n\\n\\nclass PinnedHTTPSConnection(http.client.HTTPSConnection):\\n    def __init__(self, host, port, address, timeout, context):\\n        super().__init__(host, port, timeout=timeout, context=context)\\n        self.approved_address = ipaddress.ip_address(address)\\n\\n    def connect(self):\\n        # Numeric socket connect avoids a second DNS lookup after admission.\\n        family = socket.AF_INET6 if self.approved_address.version == 6 else socket.AF_INET\\n        plain = socket.socket(family, socket.SOCK_STREAM)\\n        try:\\n            plain.settimeout(self.timeout)\\n            plain.connect((str(self.approved_address), self.port))\\n            self.sock = self._context.wrap_socket(plain, server_hostname=self.host)\\n        except Exception:\\n            plain.close()\\n            raise\\n\\n\\ndef exchange(binding, form, *, accepted, resolver=socket.getaddrinfo, connection_factory=PinnedHTTPSConnection):\\n    binding.validate()\\n    parsed = urlsplit(binding.endpoint)\\n    port = parsed.port or 443\\n    registered = RegisteredEndpoint('https', parsed.hostname, port, binding.allowed_cidrs)\\n    try:\\n        with request_deadline(binding.timeout_seconds):\\n            addresses = validate_destination(binding.endpoint, registered, resolver)\\n            if not binding.allowed_cidrs and any(not ipaddress.ip_address(address).is_global for address in addresses):\\n                raise SouthboundDenied('NON_GLOBAL_ADDRESS_UNREGISTERED')\\n            context = ssl.create_default_context(cafile=binding.ca_file)\\n            connection = connection_factory(parsed.hostname, port, addresses[0], binding.timeout_seconds, context)\\n            try:\\n                # Only technical headers are forwarded: no caller bearer, credential or arbitrary URL.\\n                connection.request('POST', parsed.path, body=form, headers={\\n                    'Accept': ','.join(sorted(accepted)), 'Accept-Encoding': 'identity',\\n                    'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',\\n                })\\n                with connection.getresponse() as response:\\n                    if response.status // 100 == 3:\\n                        raise RelayDenied('PROVIDER_REDIRECT_FORBIDDEN')\\n                    if response.status != 200:\\n                        raise RelayDenied('PROVIDER_HTTP_REJECTED')\\n                    values = response.headers.get_all('Content-Type', [])\\n                    media = values[0].split(';', 1)[0].strip().lower() if len(values) == 1 else ''\\n                    if media not in accepted:\\n                        raise RelayDenied('PROVIDER_MEDIA_TYPE_REJECTED')\\n                    encoding = response.headers.get('Content-Encoding', 'identity').strip().lower()\\n                    if encoding != 'identity':\\n                        raise RelayDenied('PROVIDER_ENCODING_REJECTED')\\n                    lengths = response.headers.get_all('Content-Length', [])\\n                    if len(lengths) > 1 or (lengths and (not lengths[0].isdigit() or int(lengths[0]) > binding.max_response_bytes)):\\n                        raise RelayDenied('PROVIDER_RESPONSE_TOO_LARGE')\\n                    if lengths and response.headers.get('Transfer-Encoding'):\\n                        raise RelayDenied('PROVIDER_FRAMING_REJECTED')\\n                    transfer = response.headers.get('Transfer-Encoding', '').strip().lower()\\n                    if transfer not in ('', 'chunked'):\\n                        raise RelayDenied('PROVIDER_FRAMING_REJECTED')\\n                    body = response.read(binding.max_response_bytes + 1)\\n                    if len(body) > binding.max_response_bytes:\\n                        raise RelayDenied('PROVIDER_RESPONSE_TOO_LARGE')\\n                    if lengths and len(body) != int(lengths[0]):\\n                        raise RelayDenied('PROVIDER_RESPONSE_INCOMPLETE')\\n                    return ProviderResponse(body, media)\\n            finally:\\n                connection.close()\\n    except (RelayDenied, ProviderRequestDenied, SouthboundDenied):\\n        raise\\n    except Exception:\\n        # No URL, provider response, caller intent or connection exception is exposed.\\n        raise RelayDenied('PROVIDER_UNAVAILABLE') from None\\n\\n\\ndef search(binding, body, *, resolver=socket.getaddrinfo, connection_factory=PinnedHTTPSConnection):\\n    binding.validate()\\n    admitted = validate_search_form(body, max_bytes=binding.max_request_bytes, max_intent_chars=binding.max_intent_chars)\\n    form = urlencode({'query': admitted['query'], 'format': 'application/sparql-results+json'}).encode()\\n    response = exchange(binding, form, accepted={'application/sparql-results+json', 'application/json'},\\n                        resolver=resolver, connection_factory=connection_factory)\\n    try:\\n        payload = json.loads(response.body)\\n        rows = payload['results']['bindings']\\n        if not isinstance(rows, list) or len(rows) > 50 or any(not isinstance(row, dict) for row in rows):\\n            raise ValueError()\\n    except (ValueError, KeyError, TypeError):\\n        raise RelayDenied('PROVIDER_SEARCH_RESULT_INVALID') from None\\n    return response\\n\\n\\ndef fetch(binding, body, *, resolver=socket.getaddrinfo, connection_factory=PinnedHTTPSConnection):\\n    binding.validate()\\n    admitted = validate_fetch_form(body, max_bytes=binding.max_request_bytes, namespace_prefixes=binding.namespace_prefixes)\\n    uri = admitted['canonicalUri']\\n    # IRI is query data only. No direct dereference, imports or recursive closure.\\n    # No LIMIT truncation: oversize/incomplete transport fails instead of returning a partial body.\\n    query = 'CONSTRUCT { <' + uri + '> ?p ?o . } WHERE { <' + uri + '> ?p ?o . }'\\n    form = urlencode({'query': query, 'format': 'text/turtle'}).encode()\\n    response = exchange(binding, form, accepted={'text/turtle'}, resolver=resolver, connection_factory=connection_factory)\\n    return ProviderResponse(response.body, response.media_type, 'OUTGOING_ASSERTED_SUBJECT_TRIPLES')\\n\",\"tools/semantic_provider_boundary.py\":\"\\\"\\\"\\\"Bound the existing Semantic provider request grammar; no network or deployment I/O.\\n\\nInstallation bindings supply destinations. Candidate IRIs identify semantic data;\\nthey never become a destination URL. This validator must run at the technical\\nsouthbound adapter before forwarding the admitted request to its registered endpoint.\\n\\\"\\\"\\\"\\nimport re\\nfrom urllib.parse import parse_qsl, urlsplit\\n\\n\\nclass ProviderRequestDenied(ValueError):\\n    pass\\n\\n\\nPREFIX = ('PREFIX owl: <http://www.w3.org/2002/07/owl#>\\\\n'\\n          'PREFIX skos: <http://www.w3.org/2004/02/skos/core#>\\\\n'\\n          'PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\\\\n')\\nPATTERNS = {\\n    'CLASS': '?resource a owl:Class .',\\n    'PROPERTY': 'VALUES ?kind { owl:ObjectProperty owl:DatatypeProperty } ?resource a ?kind .',\\n    'RELATIONSHIP': '?resource a owl:ObjectProperty .',\\n    'CONCEPT': '?resource a skos:Concept .',\\n    'VOCABULARY': '?resource a skos:ConceptScheme .',\\n    'ONTOLOGY': '?resource a owl:Ontology .',\\n}\\nHEAD = 'SELECT DISTINCT ?resource ?label WHERE { '\\nMIDDLE = ' OPTIONAL { ?resource rdfs:label|skos:prefLabel ?label } FILTER(CONTAINS(LCASE(STR(COALESCE(?label,?resource))),LCASE(\\\"'\\nTAIL = '\\\"))) } ORDER BY ?resource LIMIT 50'\\nLITERAL = re.compile(r'(?:[^\\\"\\\\\\\\\\\\x00-\\\\x1f]|\\\\\\\\[\\\\\\\\\\\"])*\\\\Z')\\n\\n\\ndef _form(body, max_bytes, fields):\\n    if type(max_bytes) is not int or not 1 <= max_bytes <= 65536:\\n        raise ProviderRequestDenied('REQUEST_LIMIT_INVALID')\\n    if not isinstance(body, bytes) or len(body) > max_bytes:\\n        raise ProviderRequestDenied('REQUEST_TOO_LARGE')\\n    try:\\n        text = body.decode('utf-8', errors='strict')\\n        if re.search(r'%(?![0-9A-Fa-f]{2})', text):\\n            raise ValueError()\\n        pairs = parse_qsl(text, keep_blank_values=True, strict_parsing=True,\\n                          encoding='utf-8', errors='strict', max_num_fields=len(fields))\\n    except (ValueError, UnicodeError):\\n        raise ProviderRequestDenied('REQUEST_ENCODING_INVALID') from None\\n    if len(pairs) != len(fields) or {k for k, _ in pairs} != set(fields):\\n        raise ProviderRequestDenied('REQUEST_FIELDS_INVALID')\\n    return dict(pairs)\\n\\n\\ndef validate_search_form(body, *, max_bytes, max_intent_chars):\\n    if type(max_intent_chars) is not int or not 1 <= max_intent_chars <= 2000:\\n        raise ProviderRequestDenied('INTENT_LIMIT_INVALID')\\n    form = _form(body, max_bytes, ('query', 'format'))\\n    if form['format'] != 'application/sparql-results+json':\\n        raise ProviderRequestDenied('RESPONSE_FORMAT_INVALID')\\n    query = form['query']\\n    for artifact_type, pattern in PATTERNS.items():\\n        start = PREFIX + HEAD + pattern + MIDDLE\\n        if query.startswith(start) and query.endswith(TAIL):\\n            literal = query[len(start):-len(TAIL)]\\n            if not LITERAL.fullmatch(literal):\\n                break\\n            # Only backslash and quote escapes are admitted by the owner's grammar.\\n            intent = re.sub(r'\\\\\\\\([\\\\\\\\\\\"])', r'\\\\1', literal)\\n            if not intent.strip() or len(intent) > max_intent_chars:\\n                raise ProviderRequestDenied('INTENT_INVALID')\\n            return {'artifactType': artifact_type, 'query': query}\\n    raise ProviderRequestDenied('SEARCH_GRAMMAR_REJECTED')\\n\\n\\ndef validate_fetch_form(body, *, max_bytes, namespace_prefixes):\\n    form = _form(body, max_bytes, ('uri',))\\n    uri = form['uri']\\n    if not isinstance(namespace_prefixes, (list, tuple)) or not namespace_prefixes:\\n        raise ProviderRequestDenied('NAMESPACE_BINDING_REQUIRED')\\n    for prefix in namespace_prefixes:\\n        _semantic_iri(prefix)\\n        if not prefix.endswith(('/', '#')):\\n            raise ProviderRequestDenied('NAMESPACE_BOUNDARY_REQUIRED')\\n    _semantic_iri(uri)\\n    if not any(uri.startswith(prefix) and len(uri) > len(prefix) for prefix in namespace_prefixes):\\n        raise ProviderRequestDenied('CANDIDATE_NAMESPACE_REJECTED')\\n    # Returned value is data for a bounded query at the registered provider.\\n    # Do not pass it to an HTTP client, Jena network resolver or redirect resolver.\\n    return {'canonicalUri': uri}\\n\\n\\ndef _semantic_iri(value):\\n    if not isinstance(value, str) or len(value) > 2048 or re.search(r'[\\\\x00-\\\\x20<>\\\"{}|\\\\\\\\^`]', value):\\n        raise ProviderRequestDenied('SEMANTIC_IRI_INVALID')\\n    try:\\n        parsed = urlsplit(value)\\n        port = parsed.port\\n    except ValueError:\\n        raise ProviderRequestDenied('SEMANTIC_IRI_INVALID') from None\\n    if parsed.scheme not in ('http', 'https') or not parsed.hostname or parsed.username is not None or parsed.password is not None or parsed.query or port == 0:\\n        raise ProviderRequestDenied('SEMANTIC_IRI_INVALID')\\n    if re.search(r'%(?![0-9A-Fa-f]{2})', value):\\n        raise ProviderRequestDenied('SEMANTIC_IRI_INVALID')\\n\\n\\ndef validate_provider_endpoint(value):\\n    \\\"\\\"\\\"Validate a trusted installation URL, without resolving it or claiming egress readiness.\\\"\\\"\\\"\\n    _semantic_iri(value)\\n    parsed = urlsplit(value)\\n    if parsed.scheme != 'https' or parsed.fragment or not parsed.path or parsed.path == '/':\\n        raise ProviderRequestDenied('PROVIDER_ENDPOINT_INVALID')\\n    return value\\n\",\"tools/lua/admit_semantic_provider.lua\":\"-- Invoked only in access phase AFTER openid-connect signature/scope admission.\\nlocal cjson = require('cjson.safe')\\nlocal function deny(status) return ngx.exit(status) end\\nlocal function text(v)\\n    return type(v)=='string' and #v>0 and #v<=512 and not v:find('[%c%s]')\\nend\\nlocal function decode64(v)\\n    if type(v)~='string' or v:find('[^%w_-]') then return nil end\\n    v=v:gsub('-','+'):gsub('_','/')\\n    return ngx.decode_base64(v..string.rep('=',(4-#v%4)%4))\\nend\\nlocal function encode64(v)\\n    return ngx.encode_base64(v):gsub('%+','-'):gsub('/','_'):gsub('=','')\\nend\\nlocal auth=ngx.var.http_authorization\\nlocal token=type(auth)=='string' and auth:match('^[Bb]earer%s+([^%s]+)$')\\nlocal payload=token and token:match('^[^.]+%.([^.]+)%.[^.]+$')\\nlocal raw=payload and decode64(payload)\\nlocal claims=raw and cjson.decode(raw)\\nif type(claims)~='table' then return deny(401) end\\nlocal audience_ok=claims.aud==AUDIENCE\\nif type(claims.aud)=='table' then\\n    for _,v in ipairs(claims.aud) do if v==AUDIENCE then audience_ok=true end end\\nend\\nlocal scope_ok=false\\nif type(claims.scope)=='string' then\\n    for v in claims.scope:gmatch('%S+') do if v==SCOPE then scope_ok=true end end\\nend\\nlocal now=ngx.time()\\nif claims.iss~=ISSUER or not audience_ok or not scope_ok or claims.ouf_actor_type~='SERVICE'\\n    or (claims.azp or claims.client_id)~=WORKLOAD or not TENANTS[claims.tenant_id]\\n    or not text(claims.sub) or type(claims.exp)~='number' or claims.exp%1~=0 or claims.exp<=now\\n    or type(claims.iat)~='number' or claims.iat%1~=0 or claims.iat>now\\n    or (claims.nbf~=nil and (type(claims.nbf)~='number' or claims.nbf>now)) then return deny(403) end\\nlocal method=ngx.req.get_method()\\nlocal target=ngx.var.request_uri\\nif method~=METHOD or type(target)~='string' or #target>6144 or target:find('[%c%s]') then return deny(400) end\\nif METHOD=='POST' and target~=PATH then return deny(400) end\\nif METHOD=='GET' and target:sub(1,#PATH+1)~=PATH..'?' then return deny(400) end\\nngx.req.read_body()\\nlocal body=ngx.req.get_body_data() or ''\\n-- Disk-buffered input is rejected rather than treated as an empty request.\\nif ngx.req.get_body_file() or #body>MAX_REQUEST_BYTES or (METHOD=='GET' and #body>0) then return deny(413) end\\nlocal key=os.getenv(RECEIPT_KEY_ENV)\\nif type(key)~='string' or #key~=64 or key:find('[^0-9a-fA-F]') then return deny(503) end\\nlocal digest=require('resty.openssl.digest').new('sha256')\\nlocal hash=digest and digest:final(method..'\\\\n'..target..'\\\\n'..body)\\nif not hash then return deny(503) end\\nlocal receipt={purpose='ouf-semantic-provider-owner-v1',installation=INSTALLATION,\\n    issuer=ISSUER,audience=AUDIENCE,workload=WORKLOAD,tenant=claims.tenant_id,\\n    subject=claims.sub,actor='SERVICE',scope=SCOPE,requestHash=require('resty.string').to_hex(hash),\\n    iat=now,exp=math.min(claims.exp,now+30)}\\nlocal encoded=encode64(cjson.encode(receipt))\\nif #encoded>4000 then return deny(403) end\\nlocal hmac=require('resty.openssl.hmac').new(key,'sha256')\\nlocal signed=hmac and hmac:final('ouf-semantic-provider-owner-v1.'..encoded)\\nif not signed then return deny(503) end\\n-- Preserve only protocol headers. The adapter receives no caller OAuth credential.\\nfor name,_ in pairs(ngx.req.get_headers(0)) do\\n    local lower=name:lower()\\n    if lower:sub(1,6)=='x-ouf-' or lower=='authorization' or lower=='cookie'\\n        or lower=='x-access-token' or lower=='x-id-token' or lower=='x-userinfo' then ngx.req.clear_header(name) end\\nend\\nngx.req.set_header('X-OUF-Semantic-Provider-Receipt',encoded..'.'..require('resty.string').to_hex(signed))\\n\"}")


TRUST_NAMES = ('ca.crt', 'trust-bundle.pem', 'adapter/server.crt', 'adapter/server.key',
               'adapter/provider-receipt.key', 'southbound/server.crt', 'southbound/server.key',
               'southbound/provider-receipt.key')
SOURCE_NAMES = tuple(k for k in GATEWAY_SOURCES if k != 'tools/materialize_semantic_provider_tls.py')
class Blocked(ValueError): pass
def require(ok, reason='MOUNT_INPUT_REVIEW_UNPROVEN'):
    if not ok: raise Blocked(reason)

class Budget:
    def __init__(self, seconds=60):
        require(type(seconds) is int and 1 <= seconds <= 60)
        self.deadline = time.monotonic()+seconds
    def check(self): require(time.monotonic() < self.deadline, 'REVIEW_DEADLINE')
    def timeout(self):
        self.check(); return min(3, self.deadline-time.monotonic())

def read(path, uid, gid, mode, limit, budget):
    budget.check(); require(path.is_absolute() and '..' not in path.parts)
    for parent in path.parents:
        info=parent.lstat()
        require(stat.S_ISDIR(info.st_mode) and info.st_uid == 0 and not info.st_mode & 0o022)
    parent=path.parent.lstat();require(parent.st_gid == 0 and stat.S_IMODE(parent.st_mode) == 0o700)
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK)
    try:
        before=os.fstat(fd)
        require(stat.S_ISREG(before.st_mode) and before.st_uid == uid and before.st_gid == gid
                and stat.S_IMODE(before.st_mode) == mode and before.st_nlink == 1 and 0 < before.st_size <= limit)
        raw=os.read(fd,limit+1);budget.check()
        require(len(raw) == before.st_size and attrs(before) == attrs(os.fstat(fd)) == attrs(path.lstat()))
        return raw,attrs(before)
    finally: os.close(fd)

def compiler():
    # Only reviewed, embedded public source is executed. Private JSON is data.
    # The original Lua file read is replaced by that same frozen Lua text.
    saved={k:v for k,v in sys.modules.items() if k == 'tools' or k.startswith('tools.')}
    package=types.ModuleType('tools');package.__path__=[];sys.modules['tools']=package
    order=('southbound_security','semantic_provider_boundary','semantic_provider_admission',
           'semantic_provider_relay','semantic_provider_adapter','materialize_semantic_provider',
           'materialize_semantic_provider_runtime','materialize_semantic_provider_tls')
    try:
        for name in order:
            key='tools.'+name;module=types.ModuleType(key);module.__file__='<ouf-reviewed-compiler>'
            sys.modules[key]=module;setattr(package,name,module)
            source=GATEWAY_SOURCES['tools/'+name+'.py']
            if name == 'materialize_semantic_provider':
                old="(Path(__file__).parent/'lua/admit_semantic_provider.lua').read_text()"
                require(source.count(old) == 1)
                module.FROZEN_LUA=GATEWAY_SOURCES['tools/lua/admit_semantic_provider.lua']
                source=source.replace(old,'FROZEN_LUA')
            exec(compile(source,'<ouf-reviewed-compiler>','exec'),module.__dict__)
        return package.materialize_semantic_provider_runtime.compile_plan, package.materialize_semantic_provider_tls.materialize_tls
    finally:
        for key in list(sys.modules):
            if key == 'tools' or key.startswith('tools.'):sys.modules.pop(key)
        sys.modules.update(saved)

class Crypto:
    def __init__(self, path, budget, public_scratch=Path('/tmp')):
        self.path,self.budget,self.public_scratch=path,budget,public_scratch
        info=public_scratch.lstat()
        require(public_scratch.is_absolute() and '..' not in public_scratch.parts
                and stat.S_ISDIR(info.st_mode) and info.st_uid == 0
                and (not info.st_mode & 0o022 or bool(info.st_mode & stat.S_ISVTX)))
        for parent in public_scratch.parents:
            info=parent.lstat()
            require(stat.S_ISDIR(info.st_mode) and info.st_uid == 0 and not info.st_mode & 0o022)
        self.binary_hash=self.binary()
    def binary(self):
        self.budget.check();require(self.path.is_absolute() and '..' not in self.path.parts)
        for parent in self.path.parents:
            s=parent.lstat();require(stat.S_ISDIR(s.st_mode) and s.st_uid == 0 and not s.st_mode & 0o022)
        fd=os.open(self.path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK)
        try:
            before=os.fstat(fd)
            require(stat.S_ISREG(before.st_mode) and before.st_uid == 0 and before.st_mode & 0o111
                    and not before.st_mode & 0o022 and 0 < before.st_size <= 64000000)
            h=hashlib.sha256();size=0
            while True:
                self.budget.check();raw=os.read(fd,65536)
                if not raw:break
                size+=len(raw);require(size <= 64000000);h.update(raw)
            require(size == before.st_size and attrs(before) == attrs(os.fstat(fd)) == attrs(self.path.lstat()))
            return h.hexdigest()
        finally:os.close(fd)
    def run(self, args, raw, fds=(), allow_failure=False):
        require(self.binary() == self.binary_hash)
        # stdout is public DER or a verification result; private key input is
        # passed only through stdin. stderr is discarded, never disclosed.
        with tempfile.TemporaryFile(dir=self.public_scratch) as output:
            child=subprocess.run([str(self.path),*args],input=raw,stdout=output,stderr=subprocess.DEVNULL,
                pass_fds=fds,timeout=self.budget.timeout(),env={'PATH':'/usr/bin:/bin','LC_ALL':'C','OPENSSL_CONF':'/dev/null'})
            output.seek(0);value=output.read(16385)
        require(len(value) <= 16384 and (allow_failure or child.returncode == 0),'CRYPTO_CHECK_UNPROVEN')
        require(self.binary() == self.binary_hash);return child.returncode,value
    def validate_pair(self, cert, key, ca, hostname):
        require(type(hostname) is str and len(hostname) <= 253
                and all(re.fullmatch(r'[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?',p) for p in hostname.split('.')))
        _,public=self.run(['x509','-pubkey','-noout'],cert)
        _,certificate_der=self.run(['pkey','-pubin','-outform','DER'],public)
        _,key_der=self.run(['pkey','-pubout','-outform','DER','-passin','pass:'],key)
        require(hmac.compare_digest(certificate_der,key_der),'TLS_KEY_PAIR_MISMATCH')
        # Only public CA bytes are materialized in a root-owned temporary
        # directory. Private keys and configuration never touch scratch files.
        with tempfile.TemporaryDirectory(prefix='ouf-public-ca-',dir=self.public_scratch) as directory:
            path=Path(directory)/'ca.pem'
            fd=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
            try:require(os.write(fd,ca) == len(ca))
            finally:os.close(fd)
            base=['verify','-no-CApath','-no-CAstore','-no-CAfile','-CAfile',str(path),
                  '-purpose','sslserver','-verify_hostname']
            self.run(base+[hostname],cert)
            rc,_=self.run(base+['ouf-negative-hostname.invalid'],cert,allow_failure=True)
            require(rc != 0,'WRONG_TLS_IDENTITY_NOT_DENIED')
            require(path.read_bytes() == ca,'CRYPTO_CHECK_UNPROVEN')


def review(raws, trust_raws, manifest_hash, installation, tls_root, trust_root, crypto):
    require(set(trust_raws) == set(TRUST_NAMES))
    previous=project(raws,manifest_hash,installation)
    values={k:decode(raw,end=k == 'apisix.yaml') for k,raw in raws.items()}
    tr,t,stage,binding,plan=(values[k] for k in ('trust','tls','stage','binding','plan'))
    source_hashes={k:sha(GATEWAY_SOURCES[k].encode()) for k in SOURCE_NAMES}
    require(stage.get('sourceHashes') == source_hashes,'STAGED_COMPILER_SOURCE_DRIFT')
    runtime_hashes={k:sha(trust_raws[k]) for k in TRUST_NAMES}
    require(t['intent'].get('runtimeTrustHashes') == runtime_hashes,'TLS_RUNTIME_TRUST_DRIFT')
    require(all(tr.get('artifactHashes',{}).get(k) == h for k,h in runtime_hashes.items()),'TRUST_ARTIFACT_HASH_DRIFT')
    require(all(b'PRIVATE KEY' not in trust_raws[k] for k in ('ca.crt','trust-bundle.pem','adapter/server.crt','southbound/server.crt')))
    require(trust_raws['trust-bundle.pem'].endswith(trust_raws['ca.crt']),'TRUST_BUNDLE_LOCAL_CA_MISSING')
    mac=trust_raws['adapter/provider-receipt.key']
    require(re.fullmatch(b'[0-9a-f]{64}',mac) and hmac.compare_digest(mac,trust_raws['southbound/provider-receipt.key']),
            'PURPOSE_MAC_PAIR_DRIFT')
    for role in ('adapter','southbound'):
        crypto.validate_pair(trust_raws[role+'/server.crt'],trust_raws[role+'/server.key'],trust_raws['ca.crt'],
                             binding['tlsIdentities'][role+'Hostname'])
    compile_plan,materialize_tls=compiler()
    require(compile_plan(copy.deepcopy(binding)) == plan,'INDEPENDENT_RUNTIME_PLAN_DRIFT')
    listener=t['intent']['listener']
    require(listener['hostname'] == binding['tlsIdentities']['southboundHostname'])
    bootstrap=materialize_tls(copy.deepcopy(binding['routes']),{'listenAddress':listener['address'],
        'listenPort':listener['port'],'serverHostname':listener['hostname'],'sslResourceId':listener['sslResourceId']},
        certificate_pem=trust_raws['southbound/server.crt'].decode('ascii'),
        private_key_pem=trust_raws['southbound/server.key'].decode('ascii'))
    regenerated={'adapter.json':json.dumps(binding['adapter'],sort_keys=True).encode()+b'\n',
        'config.yaml':json.dumps(bootstrap['runtimeConfiguration'],sort_keys=True).encode()+b'\n',
        'apisix.yaml':json.dumps(bootstrap['resources'],sort_keys=True).encode()+b'\n#END\n'}
    require(all(raws[k] == raw for k,raw in regenerated.items()),'INDEPENDENT_TLS_COMPILER_DRIFT')
    specs=values['manifest']['containers'];require(type(specs) is list and len(specs) == 2)
    expected={'adapter':{'adapter.json':str(tls_root/'adapter.json'),**{k:str(trust_root/k) for k in
        ('adapter/server.crt','adapter/server.key','adapter/provider-receipt.key','trust-bundle.pem')}},
        'southbound':{k:str(tls_root/k) for k in ('config.yaml','apisix.yaml')}}
    expected['southbound']['trust-bundle.pem']=str(trust_root/'trust-bundle.pem')
    destinations={'adapter/server.crt':binding['adapter']['tlsCertificateFile'],
        'adapter/server.key':binding['adapter']['tlsPrivateKeyFile'],
        'adapter/provider-receipt.key':binding['adapter']['receiptKeyFile'],
        'trust-bundle.pem':binding['adapter']['provider']['ca_file']}
    roles=set();mounts=[]
    for spec in specs:
        require(type(spec.get('readOnlyRoot')) is bool)
        role='adapter' if spec['readOnlyRoot'] else 'southbound';require(role not in roles);roles.add(role)
        rows=spec['mounts'];require(type(rows) is list and len(rows) == len(expected[role]))
        require({m['source'] for m in rows} == set(expected[role].values()) and len({m['target'] for m in rows}) == len(rows))
        for slot,source in expected[role].items():
            row=next(x for x in rows if x['source'] == source);target=row['target']
            require(row['readOnly'] is True and type(target) is str and Path(target).is_absolute() and '..' not in Path(target).parts)
            if slot in destinations:require(target == destinations[slot],'MOUNT_DESTINATION_BINDING_DRIFT')
            raw=raws[slot] if slot in regenerated else trust_raws[slot]
            mounts.append({'role':role,'slot':slot,'sourceBindingHash':sha(source.encode()),
                'destinationBindingHash':sha(target.encode()),'contentHash':sha(raw),'readOnly':True})
    return {'schema':'ouf.semantic-static-mount-input-review.v1','inputHashes':previous['inputHashes'],
        'trustArtifactHashes':runtime_hashes,'reviewedCompilerCommit':GATEWAY_SOURCE_COMMIT,
        'reviewedCompilerHashes':{k:sha(v.encode()) for k,v in GATEWAY_SOURCES.items()},
        'manifestMountCount':len(mounts),'manifestMountInputs':mounts,'manifestMountMappingConsistent':True,
        'independentCompilerReplay':True,'cryptographicKeyValidation':True,'serverPurposeAndHostnameValidated':True,
        'wrongHostnameDenied':True,'purposeMacPairConsistent':True,'separateTlsPrivateKeyFilesRead':2,
        'purposeMacFilesRead':2,'publicTrustFilesRead':4,'inlineTlsPrivateKeyFileRead':True,
        'caPrivateKeyRead':False,'privateMaterialSpooled':False,'publicCaTemporaryFilesUsed':True,'deploymentSigningKeysRead':False,'environmentRead':False,
        'certificateRevocationChecked':False,'imagePublisherProvenanceVerified':False,
        'currentTargetInspected':False,'fullOciAcceptanceProven':False,'generationObserved':False,
        'atomicSnapshotProven':False,'acceptanceGranted':False,'runtimeRegistered':False,'startAuthorized':False,
        'providerCalls':0,'signaturesIssued':0,'targetFilesWritten':0}

def verify(paths, metadata, pin, installation, tls_root, trust_root, crypto, budget, reader=read):
    require(set(paths) == set(metadata) == set(NAMES)|{'trust:'+k for k in TRUST_NAMES})
    first={k:reader(paths[k],*metadata[k],budget) for k in paths}
    result=review({k:first[k][0] for k in NAMES},{k:first['trust:'+k][0] for k in TRUST_NAMES},
                  pin,installation,tls_root,trust_root,crypto)
    require(first == {k:reader(paths[k],*metadata[k],budget) for k in paths},'INPUTS_CHANGED_DURING_REVIEW')
    result['opensslBinarySha256']=crypto.binary_hash;budget.check();return result

def main():
    try:
        p=argparse.ArgumentParser(description=__doc__)
        for k in ('manifest','launch','tls','trust','stage'):p.add_argument('--'+k+'-root',type=Path,required=True)
        p.add_argument('--openssl-path',type=Path,required=True)
        p.add_argument('--public-scratch-root',type=Path,required=True)
        for k in ('manifest-hash','installation'):p.add_argument('--'+k,required=True)
        for k in ('adapter-uid','adapter-gid','gateway-uid','gateway-gid'):p.add_argument('--'+k,type=int,required=True)
        a=p.parse_args();require(os.geteuid() == 0 and sys.flags.isolated and sys.dont_write_bytecode)
        require(all(type(v) is int and 0 <= v <= 2147483647 for v in (a.adapter_uid,a.adapter_gid,a.gateway_uid,a.gateway_gid)))
        budget=Budget();crypto=Crypto(a.openssl_path,budget,a.public_scratch_root)
        paths={'manifest':a.manifest_root/'stopped-manifest.json','launch':a.launch_root/'launch-input-receipt.json',
            'tls':a.tls_root/'tls-runtime-receipt.json','trust':a.trust_root/'trust-receipt.json','stage':a.stage_root/'stage-receipt.json',
            'binding':a.stage_root/'binding.json','plan':a.stage_root/'runtime-plan.json'}
        paths.update({k:a.tls_root/k for k in NAMES[7:]});paths.update({'trust:'+k:a.trust_root/k for k in TRUST_NAMES})
        meta={k:(0,0,0o600,131072) for k in paths}
        for k in ('adapter.json',):meta[k]=(a.adapter_uid,a.adapter_gid,0o600,131072)
        for k in ('config.yaml','apisix.yaml'):meta[k]=(a.gateway_uid,a.gateway_gid,0o600,131072)
        for k in TRUST_NAMES:
            role=k.split('/')[0]
            owner=(a.adapter_uid,a.adapter_gid) if role == 'adapter' else (a.gateway_uid,a.gateway_gid)
            meta['trust:'+k]=(*owner,0o600,65536) if '/' in k else (0,0,0o644,1048576)
        result=verify(paths,meta,a.manifest_hash,a.installation,a.tls_root,a.trust_root,crypto,budget)
        print('SEMANTIC_MOUNT_INPUTS='+json.dumps(result,sort_keys=True))
        print('SEMANTIC_MOUNT_INPUTS=PASS ACCEPTANCE_GRANTED=false START_AUTHORIZED=false');return 0
    except Exception as error:
        reason=str(error) if type(error) is Blocked and str(error) in {'REVIEW_DEADLINE','CRYPTO_CHECK_UNPROVEN',
            'TLS_KEY_PAIR_MISMATCH','WRONG_TLS_IDENTITY_NOT_DENIED','STAGED_COMPILER_SOURCE_DRIFT','TLS_RUNTIME_TRUST_DRIFT',
            'TRUST_ARTIFACT_HASH_DRIFT','TRUST_BUNDLE_LOCAL_CA_MISSING','PURPOSE_MAC_PAIR_DRIFT','INDEPENDENT_RUNTIME_PLAN_DRIFT',
            'INDEPENDENT_TLS_COMPILER_DRIFT','MOUNT_DESTINATION_BINDING_DRIFT','INPUTS_CHANGED_DURING_REVIEW'} else 'MOUNT_INPUT_REVIEW_UNPROVEN'
        print('SEMANTIC_MOUNT_INPUTS=BLOCKED REASON='+reason+' NO_SECRETS_PRINTED=true');return 1

if __name__ == '__main__':raise SystemExit(main())
